// Phase 9: JavaScript port of doomsday/resource (V2 16-17). Python is the reference implementation; parity is enforced by
// app/test/parity.test.mjs against fixtures generated by scripts/make_js_fixtures.py. EVIDENCE: [ESTIMATED] analytical model.
// Defaults are uncalibrated (calibrated = false); a kappa dict from E14 makes it 'partial', exactly as in Python.

export const SCENARIOS = ["optimistic", "realistic", "pessimistic"];
export const PREPS = ["v2_assumed", "tree_counted", "be_counted"];

export function pyRound(x) {                      // Python 3 round(): ties to even
  const f = Math.floor(x), d = x - f;
  if (d > 0.5) return f + 1; if (d < 0.5) return f;
  return f % 2 === 0 ? f : f + 1;
}
export function combBig(n, k) {
  if (k < 0 || k > n) return 0n; k = Math.min(k, n - k); let r = 1n;
  for (let i = 1; i <= k; i++) r = (r * BigInt(n - k + i)) / BigInt(i);
  return r;
}
export const comb = (n, k) => Number(combBig(n, k));

export const DEFAULT_PARAMS = Object.freeze({
  b: 16, R: 4, k_eff_factor: 3.0, D: 20, c_lab: 19.0, c_rot: 20.0, and_overhead: 2.0, t_toffoli_s: 10e-6, c_q: 4.0, t_classical_s: 0.5e-3,
  P: 1, Pq: 1, kappa: 1.0, alpha: 1.0, uncompute_factor: 2.0, c_tail: 0.0, verif_per_qcall: 0.5, p_ratio: 0.1, logical_budget_eps: 0.1,
  factory_routing_overhead: 0.5,
});
export const params = (over = {}) => ({ ...DEFAULT_PARAMS, ...over });
export const keffOf = (p, k) => pyRound(p.k_eff_factor * k);

// ---- components (V2 16.2) ----
export function roundComponents(L, B, keff, b, D, c_lab, scenario) {
  if (!SCENARIOS.includes(scenario)) throw new Error(`scenario must be one of ${SCENARIOS}`);
  const m = keff, comp = { island_detection: c_lab * L * D, phi_qrom_lookups: m * L, comparators_trip_update: L * b, served_load_accumulation: B * b };
  if (scenario === "optimistic" || scenario === "realistic") { comp.rank_K_flow_update = L * m * b * b; comp.small_inverse = (m ** 3) * b * b / 3.0; }
  if (scenario === "realistic" || scenario === "pessimistic") comp.injection_update_PTDF_dP = L * B * b * b;
  if (scenario === "pessimistic") comp.full_gaussian_elimination = (B ** 3) * b * b / 3.0;
  return comp;
}
const sum = (o) => Object.values(o).reduce((a, v) => a + v, 0);
export const onceOnlyCost = (L, k, b) => k * L * Math.ceil(Math.log2(Math.max(L, 2))) + b;
export const oracleComputeCost = (L, B, k, R, keff, b, D, c_lab, sc) => R * sum(roundComponents(L, B, keff, b, D, c_lab, sc)) + onceOnlyCost(L, k, b);
export function groverIterationCost(Ef, CD, L, uncompute = 2.0) {
  const parts = { oracle_compute_and_uncompute: uncompute * Ef, dicke_prep_U_and_Udagger: 2.0 * CD, reflection_multicontrolled_Z: L };
  return { G: sum(parts), parts };
}

// ---- calibration (Phase 11) ----
export const COMPONENT_TO_PRIMITIVE = { island_detection: "island_detection", rank_K_flow_update: "multiplier_flow_update",
  injection_update_PTDF_dP: "multiplier_flow_update", comparators_trip_update: "comparators_trip", served_load_accumulation: "served_load_accumulation",
  phi_qrom_lookups: "qrom_sensitivity_lookup", small_inverse: null, full_gaussian_elimination: "multiplier_flow_update" };
export function applyKappa(components, kappa) {
  if (!kappa) return { scaled: { ...components }, calibrated: false };
  const scaled = {}, prov = {};
  for (const [c, v] of Object.entries(components)) {
    const prim = COMPONENT_TO_PRIMITIVE[c];
    if (prim == null || !(prim in kappa)) { scaled[c] = v; prov[c] = "UNCALIBRATED (no A2 counterpart; kappa = 1)"; }
    else { scaled[c] = v * kappa[prim]; prov[c] = `kappa_cal(${prim})`; }
  }
  return { scaled, prov, calibrated: "partial" };
}

// ---- Dicke preparation (three scenarios, never equivalent) ----
export const dickePrepCostV2 = (L, k, c_rot) => k * L * c_rot;
export function dickeTreeOpCounts(n, k) {
  const out = {};
  for (let q = n - 1; q >= 0; q--) {
    const l = n - 1 - q; let cnt = 0;
    for (let w = 0; w <= k; w++) if (1 <= k - w && k - w <= q + 1) cnt += comb(l, w);
    if (cnt) out[l] = cnt;
  }
  return out;
}
export function dickePrepCostTree(L, k, c_rot, andOverhead = 2.0) {
  const counts = dickeTreeOpCounts(L, k); let te = 0, mx = 0;
  for (const [c, m] of Object.entries(counts)) { te += m * (andOverhead * Math.max(+c - 1, 0) + c_rot); mx = Math.max(mx, +c); }
  return { toffoli_equivalents: te, n_rotations: sum(counts), ancillas_for_and_ladder: Math.max(mx - 1, 0) };
}
export const beBlockCount = (L, k) => (k === 0 || k === L) ? 0 : (L - k) * k + Math.floor(k * (k - 1) / 2);
export function dickePrepCostBE(L, k, c_rot, andOverhead = 2.0) {
  const nb = beBlockCount(L, k), one = (0 < k && k < L) ? (L - k) + Math.max(k - 1, 0) : 0, two = nb - one;
  return { blocks: nb, one_control_rotations: one, two_control_rotations: two, toffoli_equivalents: one * c_rot + two * (c_rot + andOverhead) };
}

// ---- crossover (V2 16.1) ----
export const quantumTime = (N, G, tT, cq, M = 1, Pq = 1) => cq * Math.sqrt(N / M) * G * tT / Math.sqrt(Pq);
export const classicalTime = (N, tc, P = 1, kappa = 1.0, alpha = 1.0) => kappa * (N ** alpha) * tc / P;
export function crossoverN(G, tT, tc, P, cq, Pq = 1, kappa = 1.0, alpha = 1.0, M = 1) {
  if (alpha <= 0.5) return Infinity;
  return (cq * G * tT * P / (kappa * tc * Math.sqrt(Pq) * Math.sqrt(M))) ** (1.0 / (alpha - 0.5));
}
export function kBracket(L, N) {                  // exact comparisons, like Python's integer comb
  if (!Number.isFinite(N)) return null;
  let k = 0; const Nb = BigInt(Math.floor(N));   // exact integer value of the double, like Python's int/float comparison
  while (k < L && combBig(L, k + 1) <= Nb && combBig(L, k + 1) >= combBig(L, k)) k++;
  return [k, k < L ? k + 1 : null];
}

// ---- qubits (V2 16.4) ----
export function logicalQubits(L, B, keff, b, R, scenario, searchRegister = null, workspace = null) {
  const parts = { search_register: searchRegister ?? L, in_service_register: L, retained_round_registers: R * (L * b + L), arithmetic_workspace: workspace ?? 4 * b };
  if (scenario === "realistic" || scenario === "pessimistic") parts.held_phi_columns = keff * L * b;
  if (scenario === "pessimistic") parts.dense_matrix = B * B * b;
  return { total: sum(parts), parts };
}
export function codeDistance(volume, pRatio = 0.1, eps = 0.1, prefactor = 0.1, st = 1.0) {
  let d = 3;
  while (st * volume * prefactor * pRatio ** ((d + 1) / 2) > eps) { d += 2; if (d > 201) throw new Error("code distance > 201"); }
  return d;
}
export function physicalQubits(nLogical, volume, pRatio = 0.1, eps = 0.1, overhead = 0.5, conservative = false) {
  const d = codeDistance(volume, pRatio, eps, 0.1, conservative ? nLogical : 1.0);
  return { code_distance: d, physical_per_logical: 2 * d * d, physical_total: nLogical * 2 * d * d * (1 + overhead) };
}

// ---- evaluate (subset of Python scenarios.evaluate used by the explorer and tested for parity) ----
export function evaluate(L, B, k, scenario = "realistic", prep = "v2_assumed", p = DEFAULT_PARAMS, M = 1, kappa = null) {
  if (!SCENARIOS.includes(scenario) || !PREPS.includes(prep)) throw new Error(`bad scenario/prep ${scenario}/${prep}`);
  if (!(Number.isInteger(L) && Number.isInteger(B) && Number.isInteger(k)) || L < 1 || B < 1 || k < 1 || k > L) throw new Error("need integers L,B >= 1, 1 <= k <= L");
  const keff = keffOf(p, k), N = comb(L, k);
  let Ef = oracleComputeCost(L, B, k, p.R, keff, p.b, p.D, p.c_lab, scenario);
  if (kappa) Ef = p.R * sum(applyKappa(roundComponents(L, B, keff, p.b, p.D, p.c_lab, scenario), kappa).scaled) + onceOnlyCost(L, k, p.b);
  let CD, ancillas = 0;
  if (prep === "v2_assumed") CD = dickePrepCostV2(L, k, p.c_rot);
  else if (prep === "be_counted") CD = dickePrepCostBE(L, k, p.c_rot, p.and_overhead).toffoli_equivalents;
  else { const t = dickePrepCostTree(L, k, p.c_rot, p.and_overhead); CD = t.toffoli_equivalents; ancillas = t.ancillas_for_and_ladder; }
  const g = groverIterationCost(Ef, CD, L, p.uncompute_factor), G = g.G;
  const Q = p.c_q * Math.sqrt(N / M), TqOracle = quantumTime(N, G, p.t_toffoli_s, p.c_q, M, p.Pq);
  const V = p.verif_per_qcall * Q, Tverif = V * p.t_classical_s, Tc = classicalTime(N, p.t_classical_s, p.P, p.kappa, p.alpha);
  const Nstar = crossoverN(G, p.t_toffoli_s, p.t_classical_s, p.P, p.c_q, p.Pq, p.kappa, p.alpha, M);
  const lq = logicalQubits(L, B, keff, p.b, p.R, scenario, L); if (prep === "tree_counted") lq.total += ancillas;
  const volume = Q * G, Tq = TqOracle + Tverif;
  return { evidence: "[ESTIMATED] analytical resource model (JavaScript port; Python is the reference)", calibrated: kappa ? "partial" : false,
    N, k_eff: keff, G, E_f: Ef, C_D: CD, Q, Tq_oracle_s: TqOracle, verifications: V, Tverif_s: Tverif, Tq_s: Tq, Tc_s: Tc, ratio_Tq_over_Tc: Tq / Tc,
    quantum_faster: Tq < Tc, N_star: Nstar, k_bracket: Number.isFinite(Nstar) ? kBracket(L, Nstar) : null, logical_qubits: lq.total,
    physical_qubits: physicalQubits(lq.total, volume, p.p_ratio, p.logical_budget_eps, p.factory_routing_overhead).physical_total };
}
export const sweepK = (L, B, ks, sc, prep, p = DEFAULT_PARAMS, kappa = null) => ks.map((k) => { const r = evaluate(L, B, k, sc, prep, p, 1, kappa); return { k, N: r.N, G: r.G, Tq_s: r.Tq_s, Tc_s: r.Tc_s, ratio: r.ratio_Tq_over_Tc, N_star: r.N_star, quantum_faster: r.quantum_faster }; });
export function kStar(L, B, sc, prep, p = DEFAULT_PARAMS, kmax = null, kappa = null) {
  kmax = kmax ?? Math.min(L, 60);
  for (let k = 1; k <= kmax; k++) if (evaluate(L, B, k, sc, prep, p, 1, kappa).quantum_faster) return k;
  return null;
}
